import{_ as a,a as o,b as s,c as e,d as r}from"./chunks/cg_4.zHWnKZIH.js";import{_ as i,c as l,o as c,ae as d}from"./chunks/framework.Cd-3tpCq.js";const b=JSON.parse('{"title":"分类功能","description":"学习如何使用 MinecraftSounds 的分类功能","frontmatter":{"title":"分类功能","description":"学习如何使用 MinecraftSounds 的分类功能"},"headers":[],"relativePath":"tutorials/category.md","filePath":"tutorials/category.md"}'),n={name:"tutorials/category.md"};function u(p,t,_,m,h,k){return c(),l("div",null,t[0]||(t[0]=[d('<hr><h1 id="分类" tabindex="-1">分类 <a class="header-anchor" href="#分类" aria-label="Permalink to &quot;分类&quot;">​</a></h1><p>分类功能，用于方便归纳音频文件，比如建造关卡的时候，第一关的音频都可以放到第一关里。</p><p>分类功能的按钮在音频列表的右上角，如图所示：<br><img src="'+a+'" alt="分类"></p><h1 id="如何使用分类" tabindex="-1">如何使用分类 <a class="header-anchor" href="#如何使用分类" aria-label="Permalink to &quot;如何使用分类&quot;">​</a></h1><ol><li>点击「添加分类」按钮 <img src="'+o+'" alt="添加分类"></li><li>在弹出的对话框中输入分类名称 <img src="'+s+'" alt="添加分类"></li></ol><div class="warning custom-block"><p class="custom-block-title">注意</p><p>分类名称不能包含空格或特殊字符，仅允许使用小写英文字符或阿拉伯数字的组合，最好数字不要在最前面，也不要使用纯数字。</p></div><ol start="3"><li>点击「确定」按钮，提示「创建成功」，分类就添加成功了 <img src="'+e+'" alt="添加分类"></li><li>可以在音频列表中下拉选择框里切换分类 <img src="'+r+'" alt="切换分类"></li></ol><h1 id="使用分类的变化" tabindex="-1">使用分类的变化 <a class="header-anchor" href="#使用分类的变化" aria-label="Permalink to &quot;使用分类的变化&quot;">​</a></h1><p>1.7.10及以下版本： /playsound mcsd.{分类名称}.{音效soundkey} @a ~ ~ ~ 10000 1.8及以上版本： /playsound mcsd.{分类名称}.{音效soundkey} record @a ~ ~ ~ 10000</p><div class="tip custom-block"><p class="custom-block-title">提示</p><p>在使用分类的变化时，需要将 {分类名称} 替换为实际的分类名称，将 {音效soundkey} 替换为实际的音效soundkey。 例如：一个分类名称为 &quot;test&quot;，一个音效soundkey为 &quot;my_sound&quot;，则完整的 soundkey 为 &quot;mcsd.test.my_sound&quot;。</p></div>',11)]))}const q=i(n,[["render",u]]);export{b as __pageData,q as default};
